SELECT ?zone ?ps ?ts WHERE {
  ?zone a brick:Zone .
  rdfs:label ?lbl .
  FILTER (?lbl = "DataCenter_bot_ZN_6")
}

SELECT ?z ?lbl WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?lbl .
  FILTER (CONTAINS(str(?lbl), "DataCenter_bot_ZN_6"))
}

SELECT ?s ?lbl ?ts WHERE {
  ?s brick:hasLocation ?z .
  ?z rdfs:label ?lbl .
  FILTER (?lbl = "DataCenter_bot_ZN_6")
  ?s ref:hasTimeseriesId ?ts .
}

SELECT ?s ?cls WHERE {
  ?s brick:hasLocation ?z .
  ?z rdfs:label ?lbl .
  FILTER (?lbl = "DataCenter_bot_ZN_6")
  ?s a ?cls .
}

SELECT ?s ?cls ?loc ?llbl WHERE {
  ?s a brick:Electric_Power_Sensor .
